\noindent Let   $f, g \colon \rset^m \times \Omega \to \bar{\rset}$ be  two proper convex
 functions in the first argument, where $\Omega$ is endowed with a
probability distribution $\Prob$.  Then, we consider the following
general composite stochastic optimization problem:
\begin{align}
\label{eq_problem}
F^* & = \min_{x \in \rset^m} F(x) \quad \left( \eqdef f(x) + g(x) \right),
\end{align}
where the two functions have stochastic representations in the form of expectation, i.e.  $f(x) = \Exp{f(x, \xi)}$ and $ g(x) = \Exp{g(x, \xi)}$. We   assume that the expectation taken with respect to the random variable $\xi \in \Omega$ is finite
for all $x \in \textnormal{dom} \ F$. Hence we consider a flexible splitting of our stochastic objective function $F(x) =   \Exp{F(x, \xi)}$ in  composite form  as a sum of two  terms: 
$$ F(x,\xi) = f(x,\xi) + g(x,\xi). $$   In this paper we assume $f(\cdot,\xi)$ either differentiable or nondifferentiable function and we use,  with some abuse of notation, the same notation for the gradient or subgradient of $f(\cdot,\xi)$ at $x$, that is $\nabla f(x,\xi) \in \partial f(x, \xi)$, where $\partial f(x,\xi)$ is either a singleton or a nonempty convex set. The other term, $g(x,\xi)$,  is assumed to be simple and its structure known.  We usually refer to $g$ as the regularizer and use the same notation as before  $\nabla g(x,\xi) \in \partial g(x, \xi)$ for a (sub)gradient of $g(x, \xi)$ at $x$.  We  also assume in the sequel that to have access to either  an unbiased
stochastic estimates of the (sub)gradients of function $f$, i.e.:
\[ \mathbb{E}[\nabla f(x,\xi)] \in \partial f(x), \;\; \text{where}  \;\; \nabla f(x,\xi) \in \partial f(x,\xi),  \] or to
stochastic estimates of the proximal operator of $f$, i.e.:
\[   \prox_{\gamma f(\cdot,\xi)}(x) = \arg
\min\limits_{y \in \rset^m} f(y,\xi) + \frac{1}{2 \gamma} \|y
-x\|^2.\]
We refer to $\prox_{\gamma f (\cdot,\xi)}(x)$ as the proximal operator of the
function $f(\cdot,\xi)$ at $x$ with stepsize $\gamma$.  We  always assume to have access  to  stochastic estimates of the proximal operator of $g$, i.e. $ \prox_{\gamma g(\cdot,\xi)}(x) $. These are  key assumptions in our stochastic optimization to scale up the numerical algorithms. Template \eqref{eq_problem}


\noindent Let us denote by $X^*$ the optimal set of the convex problem \eqref{eq_problem} and for any $x \in \rset^m$ we denote its projection onto $X^*$ by $\overline{x}$, that is $\overline{x} = \Pi_{X^*}(x)$. In this paper we consider additionally the following assumptions:
\begin{assumption}
\label{assumption1}
The stochastic (sub)gradients
of $F$ satisfy a stochastic bounded gradient condition restricted on
any segment $[x, \; \overline{x}]$, that is there exist nonnegative
constants  $L \geq 0$ and $B \geq 0$ such that:
\begin{equation}
\label{as:main1_spg} B^2 +  L(F(x) - F(\overline{x})) \geq
\E_{\xi}[\| \nabla F(x,\xi)  \|^2 ] \quad  \forall x \in \textnormal{dom} \ F.
\end{equation}
\end{assumption}

\begin{assumption}
\label{assumption2}
The function  $F$ satisfies a quadratic functional growth condition restricted on
any segment $[x, \; \overline{x}]$, that is there exists  $\mu \geq 0$ such that:
\begin{equation}
\label{as:strong_spg} F(x) - F(\overline{x}) \geq  \frac{\mu}{2} \|x
- \overline{x}\|^2 \quad \forall x \in \textnormal{dom} \ F.
\end{equation}
\end{assumption}

\begin{algorithm}
Let $(\xi_t)_{t \in \nset}$ be an i.i.d sequence and $x_0 \in
\rset^m$. Iterate:
\begin{equation}
\label{eq_spgm}  \nabla f(x_t,\xi_t) \in\partial f(x_t,\xi_t) \quad  \text{and} \quad x_{t+1} = \prox_{\gamma_t g(\cdot,\xi_t)}(x_t - \gamma_t \nabla f(x_t,\xi_t) ),
\end{equation}
where $(\gamma_t)_{t \in \nset}$ is a strictly positive sequence of
stepsizes.
\end{algorithm}

