\begin{align}
\label{spp_basic} & \Exp{\|x_{t+1} - \overline{x}_{t+1} \|^2} \leq \\
&  \Exp{\| x_t - \overline{x}_{t} \|^2}   - \gamma_t (2 - \gamma_t L) \Exp{ F(x_t) -
F(\overline{x}_{t})}  + \gamma_t^2 \left( B^2 + B_{g}^2 \right). \nonumber
\end{align}
\end{theorem}

