& =  \| x_{t} - \overline{x}_{t} \|^2  - 2 \gamma_t \langle \mathcal{G}(x_t;\xi_t), x_t  - \overline{x}_{t} \rangle + \gamma_t^2 \| \mathcal{G}(x_t;\xi_t) \|^2  \nonumber  \\
& = \| x_{t} - \overline{x}_{t} \|^2  - 2 \gamma_t \langle \nabla
f(x_t,\xi_t) + \nabla g(x_{t+1},\xi_t), x_t  - \overline{x}_{t} \rangle +
\gamma_t^2 \| \mathcal{G}(x_t;\xi_t) \|^2.\nonumber 
\end{align}

Note that $x_t$ depends only on history $\xi_{[t-1]} =
\{\xi_0,\ldots, \xi_{t-1}\} $, not $\xi_t$. It follows from the
basic property of  conditional expectation that:
\begin{align*}
& \E_{\xi_{[t]}} [\|x_{t+1}  - \overline{x}_{t+1}\|^2] \\
& \leq \E_{\xi_{[t-1]}}[\|x_{t} - \overline{x}_{t}\|^2]  - 2 \gamma_t  \E_{\xi_{[t-1]}}
\left[ \E_{\xi_t} [ F(x_t,\xi_t) - F(\overline{x}_{t},\xi_t)  | \xi_{[t-1]}
]\right] \\
& \qquad +  \gamma_t^2 \E_{\xi_{[t]}}  \left[\| \nabla F(x_t,\xi_t) \|^2 ] \right]\\
& =  \E_{\xi_{[t-1]}}[\|x_{t} \!- \overline{x}_{t}\|^2]  - 2
\gamma_t \E_{\xi_{[t-1]}} \left[ F(x_t) - F(\overline{x}_{t})\right]
+ \gamma_t^2 \E_{\xi_{[t]}}  \left[\| \nabla F(x_t,\xi_t) \|^2 \right].
\end{align*}

