\begin{theorem}
\label{th:spp_basic} Let $f(\cdot, \xi)$ and $g(\cdot, \xi)$ be convex functions  that  admit easily computable proximal operators. Additionally, assume that the  stochastic bounded gradient condition from Assumption \ref{assumption1} holds and $g(\cdot, \xi)$ have bounded subgradients, that is there exists $B_{g}>0$ such that $ \|\nabla g(x, \xi)\| \leq B_g$ for all $x$ and $\xi$. Then, for any stepsize $\gamma_t>0$ we have the following recursive inequality for the SPP iteration:
\begin{align}
\label{spp_basic} & \Exp{\|x_{t+1} - \overline{x}_{t+1} \|^2} \leq \\
&  \Exp{\| x_t - \overline{x}_{t} \|^2}   - \gamma_t (2 - \gamma_t L) \Exp{ F(x_t) -
F(\overline{x}_{t})}  + \gamma_t^2 \left( B^2 + B_{g}^2 \right). \nonumber
\end{align}
\end{theorem}

\begin{proof}
From \eqref{sfo_basic}  and Assumption \ref{assumption2}  it follows that:
\begin{align*}
& \E_{\xi_{[t]}} [\|x_{t+1}  - \overline{x}_{t+1}\|^2] \leq
\E_{\xi_{[t-1]}}[\|x_{t} - \overline{x}_{t}\|^2]  -  \gamma_t (2 -
\gamma_t L) \E_{\xi_{[t-1]}}
\left[F(x_t) - F(\overline{x}_{t})\right]  \\
& + {\cal B}^2 \gamma_{t}^2  \overset{\eqref{as:strong_spg}}{\leq} \E_{\xi_{[t-1]}}[\|x_{t} -
\overline{x}_{t}\|^2]  - \frac{\mu \gamma_t (2 - \gamma_t L)}{2}
\E_{\xi_{[t-1]}} [\|x_{t} - \overline{x}_{t}\|^2] +  {\cal B}^2
\gamma_{t}^2,
\end{align*}

Moreover, if $\mu < 4L$, then the relation $1 - \mu \gamma + \mu L
\gamma^2/2 > -1$ always holds, regardless of the value of $\gamma$. Thus, if $\mu < 4L$ and  the constant stepsize is chosen such $\gamma < \frac{2}{L}$,  then $|1 - \mu \gamma + \mu L \gamma^2| < 1$. Similarly, if  the  constant stepsize satisfies  $\gamma < \min(2/L, 2/\mu)$, then again we have $0< 1 - \mu \gamma + \mu L \gamma^2 < 1$. Therefore, these two previous conditions guarantee linear convergence  to a noise dominated region whose radius is proportional to the square of the stepsize $\gamma$.    Finally, the inequality \eqref{recursive1_spg} with ${\cal B}=0$ and $|1 - \mu \gamma + \mu L \gamma^2| < 1$  proves  linear convergence for $\Exp{\|x_{t} - \overline{x}_{t} \|^2}$, with $x_t$ generated by SFO methods.  \qed
\end{proof}
